using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Betta.Attributes;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    [GrasshopperCollection("Facade", "Panels")]
    public interface IFacadePack : IBettaCollection
    {
        [GrasshopperMethod("Panelize Surface", "Divide a surface evenly into four-sided panels", SubCategory = "Panels")]
        (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(
            [GrasshopperParameter("Surface")] Surface surface,
            [GrasshopperParameter("U Count", DefaultValue = 10)] int uCount,
            [GrasshopperParameter("V Count", DefaultValue = 6)] int vCount);

        [GrasshopperMethod("Panel Info", "Corners, outline, area, center and index of a panel", SubCategory = "Panels")]
        (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(
            [GrasshopperParameter("Panel")] Panel panel);

        [GrasshopperMethod("Planarity", "Planarity deviation of each panel", SubCategory = "Analysis")]
        (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 0.5)] double tolerance,
            IBettaReport report);

        [GrasshopperMethod("Classify Panels", "Flat, cold-bent or custom by planarity deviation", SubCategory = "Analysis")]
        (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 0.5)] double tolerance);

        [GrasshopperMethod("Panel Stats", "Area statistics of the panels", SubCategory = "Analysis")]
        (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(
            [GrasshopperParameter("Panels")] List<Panel> panels);

        [GrasshopperMethod("Group Identical Panels", "Group panels with matching edge and diagonal lengths", SubCategory = "Fabrication")]
        (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 1.0)] double tolerance);

        [GrasshopperMethod("Nest On Sheets", "Shelf-nest panels as rectangles on sheets", SubCategory = "Fabrication")]
        Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Sheet Width", DefaultValue = 3000.0)] double sheetWidth,
            [GrasshopperParameter("Sheet Height", DefaultValue = 1500.0)] double sheetHeight,
            [GrasshopperParameter("Spacing", DefaultValue = 10.0)] double spacing,
            CancellationToken cancellationToken,
            IProgress<int> progress,
            IBettaReport report);

        [GrasshopperMethod("Cut List", "CSV cut list of the panels, optionally written to a file", SubCategory = "Fabrication")]
        (string CSV, bool Written) CutList(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Path", DefaultValue = "")] string path,
            [GrasshopperParameter("Write", DefaultValue = false)] bool write);
    }

    public class FacadePack : IFacadePack
    {
        public (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(Surface surface, int uCount, int vCount)
        {
            if (uCount < 1 || vCount < 1)
                throw new ArgumentException("U Count and V Count must be at least 1.");
            if (surface == null)
                throw new ArgumentException("Surface is required.");

            Interval du = surface.Domain(0), dv = surface.Domain(1);
            var grid = new Point3d[uCount + 1, vCount + 1];
            for (int i = 0; i <= uCount; i++)
                for (int j = 0; j <= vCount; j++)
                    grid[i, j] = surface.PointAt(du.ParameterAt((double)i / uCount), dv.ParameterAt((double)j / vCount));

            var panels = new List<Panel>();
            var outlines = new List<Curve>();
            for (int j = 0; j < vCount; j++)
                for (int i = 0; i < uCount; i++)
                {
                    var panel = new Panel(grid[i, j], grid[i + 1, j], grid[i + 1, j + 1], grid[i, j + 1], j * uCount + i);
                    panels.Add(panel);
                    outlines.Add(panel.Outline);
                }
            return (panels, outlines);
        }

        public (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(Panel panel)
        {
            if (panel == null) throw new ArgumentException("Panel is required.");
            return (panel.Corners.ToList(), panel.Outline, panel.Area, panel.Center, panel.Index);
        }

        public (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            List<Panel> panels, double tolerance, IBettaReport report)
        {
            var deviation = panels.Select(p => p.Deviation).ToList();
            var flat = deviation.Select(d => d <= tolerance).ToList();
            int flatCount = flat.Count(f => f);
            int notFlat = panels.Count - flatCount;
            if (notFlat * 2 > panels.Count)
                report.Warning($"{notFlat} of {panels.Count} panels are not flat.");
            return (deviation, flat, flatCount);
        }

        public (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            List<Panel> panels, double tolerance)
        {
            var types = new List<string>();
            foreach (var p in panels)
            {
                double d = p.Deviation;
                types.Add(d <= tolerance ? "flat" : d <= 10 * tolerance ? "cold-bent" : "custom");
            }
            return (types, types.Count(t => t == "flat"), types.Count(t => t == "cold-bent"), types.Count(t => t == "custom"));
        }

        public (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(List<Panel> panels)
        {
            if (panels == null || panels.Count == 0)
                throw new ArgumentException("No panels.");
            var areas = panels.Select(p => p.Area).ToList();
            return (areas.Sum(), areas.Min(), areas.Max(), areas.Average());
        }

        public (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            List<Panel> panels, double tolerance)
        {
            var representatives = new List<Panel>();
            var signatures = new List<double[]>();
            var group = new List<int>();
            foreach (var panel in panels)
            {
                var sig = Signature(panel);
                int g = signatures.FindIndex(s => s.Zip(sig, (a, b) => Math.Abs(a - b) <= tolerance).All(ok => ok));
                if (g < 0)
                {
                    g = signatures.Count;
                    signatures.Add(sig);
                    representatives.Add(panel);
                }
                group.Add(g);
            }
            return (group, representatives.Count, representatives);
        }

        private static double[] Signature(Panel p)
        {
            var edges = new[] { p.Edge(0), p.Edge(1), p.Edge(2), p.Edge(3) };
            var diagonals = new[] { p.Corners[0].DistanceTo(p.Corners[2]), p.Corners[1].DistanceTo(p.Corners[3]) };
            Array.Sort(edges);
            Array.Sort(diagonals);
            return edges.Concat(diagonals).ToArray();
        }

        public Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            List<Panel> panels, double sheetWidth, double sheetHeight, double spacing,
            CancellationToken cancellationToken, IProgress<int> progress, IBettaReport report)
        {
            var result = Task.Run(() =>
            {
                var parts = panels.Select(p => (w: p.Width, h: p.Height)).OrderByDescending(p => p.h).ToList();
                var outlines = new List<Curve>();
                var sheets = new List<int>();
                double placedArea = 0;
                int sheetCount = 0, skipped = 0;
                double shelfX = 0, shelfY = 0, shelfH = 0;
                bool open = false;

                bool Fits(double w, double h) => w + 2 * spacing <= sheetWidth && h + 2 * spacing <= sheetHeight;

                void Place(double w, double h)
                {
                    double ox = (sheetCount - 1) * (sheetWidth + 100);
                    outlines.Add(new PolylineCurve(new[]
                    {
                        new Point3d(ox + shelfX, shelfY, 0), new Point3d(ox + shelfX + w, shelfY, 0),
                        new Point3d(ox + shelfX + w, shelfY + h, 0), new Point3d(ox + shelfX, shelfY + h, 0),
                        new Point3d(ox + shelfX, shelfY, 0)
                    }));
                    sheets.Add(sheetCount - 1);
                    placedArea += w * h;
                    shelfX += w + spacing;
                }

                for (int n = 0; n < parts.Count; n++)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    var (w, h) = parts[n];
                    if (!Fits(w, h) && !Fits(h, w))
                    {
                        skipped++;
                    }
                    else
                    {
                        bool placed = false;
                        if (open)
                        {
                            // current shelf
                            foreach (var (pw, ph) in new[] { (w, h), (h, w) })
                            {
                                if (!placed && ph <= shelfH && shelfX + pw + spacing <= sheetWidth)
                                {
                                    Place(pw, ph);
                                    placed = true;
                                }
                            }
                            // new shelf above
                            if (!placed)
                            {
                                double y = shelfY + shelfH + spacing;
                                foreach (var (pw, ph) in new[] { (w, h), (h, w) })
                                {
                                    if (!placed && pw + 2 * spacing <= sheetWidth && y + ph + spacing <= sheetHeight)
                                    {
                                        shelfX = spacing; shelfY = y; shelfH = ph;
                                        Place(pw, ph);
                                        placed = true;
                                    }
                                }
                            }
                        }
                        // new sheet
                        if (!placed)
                        {
                            var (pw, ph) = Fits(w, h) ? (w, h) : (h, w);
                            sheetCount++;
                            open = true;
                            shelfX = spacing; shelfY = spacing; shelfH = ph;
                            Place(pw, ph);
                        }
                    }
                    if (n % 50 == 0) progress?.Report(parts.Count == 0 ? 100 : 100 * n / parts.Count);
                }
                progress?.Report(100);

                double utilization = sheetCount == 0 ? 0 : placedArea / (sheetCount * sheetWidth * sheetHeight);
                return (outlines, sheets, sheetCount, utilization, skipped);
            }, cancellationToken);

            return Finish(result, report);
        }

        private static async Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> Finish(
            Task<(List<Curve>, List<int>, int, double, int)> task, IBettaReport report)
        {
            var (outlines, sheets, count, utilization, skipped) = await task.ConfigureAwait(false);
            if (skipped > 0)
                report.Warning($"{skipped} panels do not fit on any sheet.");
            return (outlines, sheets, count, utilization);
        }

        public (string CSV, bool Written) CutList(List<Panel> panels, string path, bool write)
        {
            if (write && string.IsNullOrWhiteSpace(path))
                throw new ArgumentException("Path is required when Write is true.");

            var ci = CultureInfo.InvariantCulture;
            var sb = new StringBuilder("index,width,height,area,deviation\n");
            foreach (var p in panels)
                sb.Append(string.Join(",", p.Index.ToString(ci), p.Width.ToString("R", ci), p.Height.ToString("R", ci),
                    p.Area.ToString("R", ci), p.Deviation.ToString("R", ci))).Append('\n');
            string csv = sb.ToString();

            if (!write) return (csv, false);
            File.WriteAllText(path, csv);
            return (csv, true);
        }
    }
}

